package net.softm.bunyangalarm;
import android.app.Activity;import android.content.Intent;import android.graphics.Color;import android.net.Uri;import android.os.Bundle;import android.view.*;import android.webkit.*;import android.widget.*;import androidx.annotation.Nullable;import softm.hannun.ads.*;import softm.hannun.update.HannunInAppUpdateManager;import java.util.Collections;
public class MainActivity extends Activity{
 private WebView web;private View failure;private boolean mainFailed;private HannunAds ads;private HannunInAppUpdateManager updater;
 @Override public void onCreate(@Nullable Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);FrameLayout content=new FrameLayout(this);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));LinearLayout ad=new LinearLayout(this);root.addView(ad,new LinearLayout.LayoutParams(-1,-2));setContentView(root);web=new WebView(this);content.addView(web,new FrameLayout.LayoutParams(-1,-1));failure=failureView();content.addView(failure,new FrameLayout.LayoutParams(-1,-1));WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setUserAgentString(s.getUserAgentString()+" BunyangAlarmAndroid/1.0");HannunWebViewAds.markNativeAds(s);web.setWebViewClient(new WebViewClient(){@Override public void onPageStarted(WebView v,String u,android.graphics.Bitmap b){mainFailed=false;failure.setVisibility(View.GONE);}@Override public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())showFailure();}@Override public void onReceivedHttpError(WebView v,WebResourceRequest r,WebResourceResponse e){if(r.isForMainFrame()&&e.getStatusCode()>=400)showFailure();}@Override public void onPageFinished(WebView v,String u){v.getSettings().setCacheMode(WebSettings.LOAD_DEFAULT);if(!mainFailed)failure.setVisibility(View.GONE);}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(u.toString().startsWith(BuildConfig.WEB_URL))return false;try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception ignored){}return true;}});ads=new HannunAds(this,ad,new HannunAdConfig(getString(R.string.admob_native_ad_unit_id),getString(R.string.admob_adaptive_banner_ad_unit_id),getString(R.string.admob_interstitial_ad_unit_id),getString(R.string.admob_exit_banner_ad_unit_id)));ads.start();updater=new HannunInAppUpdateManager(this,null);if(state==null)loadFresh();else web.restoreState(state);}
 private View failureView(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setGravity(Gravity.CENTER);p.setPadding(dp(28),dp(28),dp(28),dp(28));p.setBackgroundColor(Color.rgb(255,248,250));TextView t=new TextView(this);t.setText("네트워크 연결을 확인해 주세요");t.setTextSize(20);t.setTextColor(Color.rgb(38,53,74));t.setGravity(Gravity.CENTER);p.addView(t,new LinearLayout.LayoutParams(-1,-2));TextView m=new TextView(this);m.setText("연결을 확인한 뒤 다시 시도하면 분양알람을 이어서 이용할 수 있어요.");m.setTextSize(14);m.setGravity(Gravity.CENTER);m.setPadding(0,dp(14),0,dp(20));p.addView(m,new LinearLayout.LayoutParams(-1,-2));Button b=new Button(this);b.setText("다시 시도");b.setMinHeight(dp(48));b.setOnClickListener(v->loadFresh());p.addView(b,new LinearLayout.LayoutParams(-1,dp(48)));p.setVisibility(View.GONE);return p;}private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private void showFailure(){mainFailed=true;failure.setVisibility(View.VISIBLE);}private void loadFresh(){mainFailed=false;failure.setVisibility(View.GONE);web.getSettings().setCacheMode(WebSettings.LOAD_NO_CACHE);web.loadUrl(BuildConfig.WEB_URL,Collections.singletonMap("Cache-Control","no-cache"));}
 @Override public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else if(ads!=null)ads.showExitConfirmation();else super.onBackPressed();}@Override protected void onResume(){super.onResume();if(ads!=null)ads.onResume();if(updater!=null)updater.onResume();}@Override protected void onPause(){if(ads!=null)ads.onPause();if(updater!=null)updater.onPause();super.onPause();}@Override protected void onActivityResult(int a,int b,Intent d){if(updater!=null&&updater.onActivityResult(a,b))return;super.onActivityResult(a,b,d);}@Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);if(web!=null)web.saveState(b);}@Override protected void onDestroy(){if(ads!=null)ads.destroy();if(updater!=null)updater.destroy();if(web!=null)web.destroy();super.onDestroy();}}
